#include <cstdio>
#include <cstdlib>
#include <new>

struct Region {
    float Start, Score;
    Region(float s) : Start(s), Score(-s) { }
    Region(const Region& o) : Start(o.Start), Score(o.Score) { }
    Region& operator=(const Region& o) { Start = o.Start; Score = o.Score; return *this; }
    virtual ~Region() { }
