                    ucopy(position, old_finish, _M_finish);
                    _M_finish += elems_after;
                    for (Region* p = position; p != old_finish; ++p) *p = x_copy;
                }
            } else
                overflowed = true;
        }
    }
};

static bool expect(const RegionVec& v, const float* want, int n)
