template <class RI, class T, class Cmp>
void tm_push_heap(RI first, int hole, int top, T val, Cmp comp)
{
    int parent = (hole - 1) / 2;
    while (hole > top && comp(*(first + parent), val)) {
        *(first + hole) = *(first + parent);
        hole = parent;
        parent = (hole - 1) / 2;
